</tr>
</thead>

<tbody>

${rows}

<tr>
    <th colspan="2">TOTAL</th>
    <th class="text-right">${formatNumber(result.value.totalKg)} KG</th>
    <th class="text-right">-</th>
    <th class="text-right">-</th>
    <th class="text-right">${formatRate(totalCost.value)}</th>
</tr>

<tr>
    <th colspan="2">FINAL CONCRETE VOLUME</th>
    <th class="text-right">-</th>
    <th class="text-right">${Number(cbm.value).toFixed(3)} CBM</th>
    <th class="text-right">-</th>
    <th class="text-right">-</th>
</tr>

</tbody>

</table>



<div style="margin-top:20px;font-size:10px">

<p>
<strong>Generated At:</strong>
${new Date().toLocaleString()}
</p>


<p>
<strong>Generated By:</strong>
${user?.name ?? '---'}
</p>


</div>



</body>

</html>
`;


    triggerPrint(printContent);

};
</script>